INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A', 'creative_arts', 8, 'Describe the roles of Creative Arts and Sports in society', ARRAY['CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.a']::text[], 'The child names roles (entertainment, passing on culture, keeping people fit and healthy, bringing people together, earning a living) and does not say the arts and sports have no use. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.1.1, CREA.G8.RUBRIC.1.2), never as a phone question: b) make a storyboard highlighting the roles of Creative Arts and Sports in society.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 8, 'Name the elements of verse', ARRAY['CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.a']::text[], 'The child names lines, stanzas, rhyme, rhythm and imagery as elements of verse, and says a stanza is a group of lines. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 8, 'Tell endurance from agility', ARRAY['CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.b']::text[], 'The child says endurance is keeping going for a long time without tiring and agility is changing direction quickly, and names activities for each (long running; zigzag runs). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.1.1, CREA.G8.RUBRIC.1.2), never as a phone question: b) perform activities that enhance endurance and agility in physical fitness.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 8, 'Name pitches on the bass staff', ARRAY['CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.c', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.d']::text[], 'The child says the lines of the bass staff from the bottom are G B D F A and the spaces are A C E G, and that the bass clef is for low sounds. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 8, 'Group notes in 3/4 time', ARRAY['CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.e']::text[], 'The child says 3/4 has three crotchet beats in a bar, that a dotted minim fills a bar, and that a minim and a crotchet together make three beats. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A', 'creative_arts', 8, 'Build the scale of G major', ARRAY['CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.f']::text[], 'The child says G major has one sharp, F sharp, and its notes are G A B C D E F-sharp G, starting and ending on G. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'CREA.G8.CREATI.DRAWING_AND_PAINTING', 'creative_arts', 8, 'Tell what dominance is in a picture', ARRAY['CREA.G8.CREATI.DRAWING_AND_PAINTING.a']::text[], 'The child says dominance is the main feature that catches the eye first in a picture, made by size, colour or position, and that other parts are less important. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: d) paint a still life composition to express dominance.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY', 'CREA.G8.CREATI.DRAWING_AND_PAINTING', 'creative_arts', 8, 'Name complementary colours and colour contrast', ARRAY['CREA.G8.CREATI.DRAWING_AND_PAINTING.b']::text[], 'The child says complementary colours sit opposite each other on the colour wheel (red and green, blue and orange, yellow and violet) and give strong contrast when placed together. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: c) illustrate a colour gradation strip to show colour contrast.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.RHYTHM.THREE_FOUR', 'CREA.G8.CREATI.RHYTHM', 'creative_arts', 8, 'Describe three-four time and the rhythms written in it', ARRAY['CREA.G8.CREATI.RHYTHM.a']::text[], 'The child says three-four time has three crotchet beats in every bar with the first beat strong (STRONG weak weak), that it suits waltz-like songs and dances, that a dotted minim fills a bar, and checks that every bar of a four-bar pattern adds up to three beats. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) compose a four-bar rhythmic pattern in 3 time, 4; c) perform four-bar rhythmic patterns in 3 time, 4.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE', 'CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN', 'creative_arts', 8, 'Describe middle distance races and a montage', ARRAY['CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.a', 'CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.c']::text[], 'The child says middle distance races include the 800 metres and the 1 500 metres, need pace and endurance, and that a montage is a picture made by combining many pieces or pictures. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) perform middle distance races for skill acquisition; d) create a montage composition inspired by athletes running.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.MELODY.MELODY_METHODS', 'CREA.G8.CREATI.MELODY', 'creative_arts', 8, 'Name methods of making a melody', ARRAY['CREA.G8.CREATI.MELODY.a']::text[], 'The child says a melody can be made by repeating a short idea, moving by steps and leaps, and by a question phrase answered by an answer phrase, ending on the home note G in G major. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) compose a 2-bar answering phrase to a given 2-bar opening phrase; c) compose a 4-bar melody in G major; d) perform simple pieces of music in G major.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.NETBALL.NETBALL', 'CREA.G8.CREATI.NETBALL', 'creative_arts', 8, 'Describe passes and footwork in netball', ARRAY['CREA.G8.CREATI.NETBALL.a', 'CREA.G8.CREATI.NETBALL.c']::text[], 'The child says a netball team has seven players, the passes are chest, bounce, shoulder and overhead, a player may not run with the ball, and may hold it for only three seconds. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) perform passes in Netball for skill acquisition; c) execute dodging and marking in Netball for skill development; d) perform footwork skills in a Netball game situation.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR', 'CREA.G8.CREATI.FABRIC_DECORATION', 'creative_arts', 8, 'Describe fabric decorating techniques', ARRAY['CREA.G8.CREATI.FABRIC_DECORATION.a', 'CREA.G8.CREATI.FABRIC_DECORATION.b', 'CREA.G8.CREATI.FABRIC_DECORATION.c', 'CREA.G8.CREATI.FABRIC_DECORATION.d']::text[], 'The child says tie and dye ties parts of cloth before dyeing so those parts keep their colour, pleating folds the cloth, and stencil printing passes colour through a cut-out design. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) tie and dye a fabric using marbling; c) decorate a fabric using pleating technique; d) print fabric using a stencil.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH', 'CREA.G8.CREATI.DESCANT_RECORDER', 'creative_arts', 8, 'Explain recorder techniques and performance directions', ARRAY['CREA.G8.CREATI.DESCANT_RECORDER.a', 'CREA.G8.CREATI.DESCANT_RECORDER.b']::text[], 'The child says the recorder is played by covering holes with finger pads, blowing gently with the tongue shaping each note, and reads p as soft, f as loud and a repeat sign as play again. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: c) perform simple melodies in G Major on a descant recorder.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.VERSE.VERSE_LANGUAGE', 'CREA.G8.CREATI.VERSE', 'creative_arts', 8, 'Describe language use in verse', ARRAY['CREA.G8.CREATI.VERSE.a']::text[], 'The child says verse uses simile (like or as), metaphor (one thing is another), repetition and personification to make words vivid. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) compose a verse to address an issue in society; c) perform a verse before an audience.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL', 'CREA.G8.CREATI.VOLLEYBALL', 'creative_arts', 8, 'Describe the overarm serve and volleying', ARRAY['CREA.G8.CREATI.VOLLEYBALL.a']::text[], 'The child says volleyball is played with six players a side over a net, an overarm serve hits the ball with one open hand above the head, a volley is hit with the fingertips overhead, and a team has three touches. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) serve the ball using overarm serve over a net; c) perform the volleying skill in Volleyball; d) appraise others’ efforts when applying serving and volleying skills in Volleyball.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES', 'CREA.G8.CREATI.KENYAN_FOLK_DANCE', 'creative_arts', 8, 'Classify Kenyan folk dances by community', ARRAY['CREA.G8.CREATI.KENYAN_FOLK_DANCE.a']::text[], 'The child links isukuti to the Luhya, adumu (a jumping dance) to the Maasai, chakacha to the Coast and mwomboko to the Kikuyu, and says folk dances keep culture alive. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) perform a folk dance from a Kenyan community.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY', 'CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_', 'creative_arts', 8, 'Describe coil basketry', ARRAY['CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.a']::text[], 'The child says coil basketry winds a coil of grass or sisal in a spiral and stitches it with thread, and that baskets, trays and mats are made this way. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) make a basketry item using the coil method.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES', 'CREA.G8.CREATI.SWIMMING', 'creative_arts', 8, 'Explain inverted breaststroke and water treading', ARRAY['CREA.G8.CREATI.SWIMMING.a']::text[], 'The child says the inverted breaststroke is done on the back with a frog kick and arms moving together, and water treading keeps the body upright in deep water by moving the legs and arms; swimming is only with a lifeguard. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) perform water treading skill in swimming; c) perform the inverted breaststroke technique in swimming for skill acquisition; d) combine the skills of water treading and inverted breaststroke for skill mastery.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES', 'CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES', 'creative_arts', 8, 'Describe indigenous tagging games', ARRAY['CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.a']::text[], 'The child says in a tagging game the chaser touches a runner who then becomes the chaser, and that such games build speed, agility and teamwork. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.2.1, CREA.G8.RUBRIC.2.2, CREA.G8.RUBRIC.2.3), never as a phone question: b) perform different indigenous tagging games for skill acquisition; c) perform indigenous tagging games using musical rhythm for coordination.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 8, 'Name the spirit of sportsmanship', ARRAY['CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.c']::text[], 'The child names fair play, honesty, respect for opponents and officials, and accepting defeat gracefully as sportsmanship. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART', 'creative_arts', 8, 'Analyse a verse performance and a Kenyan folk dance using the right terms', ARRAY['CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.b', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.d']::text[], 'The child analyses a verse performance by its message, language (simile, metaphor, repetition), voice and gestures, and a Kenyan folk dance by its community, occasion, formation, costume, props and instruments, backing each point with something seen or heard. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception. Practical, marked by the teacher with the KICD rubric (CREA.G8.RUBRIC.3.1, CREA.G8.RUBRIC.3.2, CREA.G8.RUBRIC.3.3), never as a phone question: a) showcase artwork for appreciation.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'CREA.G7.FOUNDA.INTRODUCTION_TO_CREATIVE.CA_CATEGORIES', 'skill', 'essential', 'Knowing the categories (Grade 7) comes before their roles in society. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'CREA.G5.PERFOR.KENYAN_FOLK_DANCE.ROLES', 'skill', 'helpful', 'The roles of folk dance in the community (Grade 5) are one example of these roles. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS', 'ENGL.G7.READIN.T3_INTENSIVE_READING_PO.POEM_STRUCTURE', 'skill', 'essential', 'Line, stanza, rhyme and refrain (Grade 7 English) are the elements of verse. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.STORY_ELEMENTS', 'skill', 'helpful', 'The elements of a story (Grade 7) come before the elements of verse. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_COMPONENTS', 'skill', 'essential', 'Naming all the components of fitness (Grade 7) comes before training two of them. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'CREA.G7.CREATI.KENYAN_INDIGENOUS_GAMES.ROPE_GAMES', 'skill', 'helpful', 'Rope games (Grade 7) build endurance and agility. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'skill', 'essential', 'Reading the treble staff (Grade 7) comes before the bass staff. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'skill', 'essential', 'Note values (Grade 7) are written on the bass staff too. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.NOTE_VALUES', 'skill', 'essential', 'Grouping notes in two-four time (Grade 7) comes before three-four time. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'CREA.G6.CREATI.RHYTHM_AND_PATTERN_MAKIN.NOTES', 'skill', 'helpful', 'The three-beat pattern and the dotted minim (Grade 6) are used again. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'CREA.G7.CREATI.MELODY.MELODY_QUALITIES', 'skill', 'essential', 'Melodies in C major (Grade 7) come before a key with a sharp. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'CREA.G7.FOUNDA.COMPONENTS_OF_CREATIVE_A.TREBLE_PITCHES', 'skill', 'essential', 'Naming notes on the staff (Grade 7) is needed to write a scale. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.BALANCE', 'skill', 'essential', 'Balance (Grade 7) is the principle met before dominance. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.TECHNIQUES', 'skill', 'helpful', 'A still life (Grade 6) is where dominance is painted. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY', 'CREA.G7.CREATI.DRAWING_AND_PAINTING.COLOUR_TEMP', 'skill', 'essential', 'Warm and cool colours (Grade 7) sit on opposite sides, as complements do. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY', 'CREA.G6.CREATI.PAINTING_AND_COLLAGE.COLOUR_WHEEL', 'skill', 'essential', 'The colour wheel (Grade 6) shows which colours are opposite. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.RHYTHM.THREE_FOUR', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.RHYTHM.THREE_FOUR', 'CREA.G7.CREATI.RHYTHM.RHYTHM_FACTORS', 'skill', 'essential', 'The factors in making a rhythm (Grade 7) are used again in three-four time. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE', 'CREA.G5.PERFOR.ATHLETICS.RELAY', 'skill', 'essential', 'Racing rules and lanes (Grade 5 relay) apply to middle distance races. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE', 'CREA.G4.CREATI.PAINTING_AND_MONTAGE.MONTAGE', 'skill', 'essential', 'Making a montage (Grade 4) is extended here to a montage of athletes. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
