INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTS_VALUES', 'skill', 'essential', 'The values of clean sport (Grade 7) are the spirit of sportsmanship. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP', 'SOCI.G8.SOCIAL.SELF_ESTEEM_ASSESSMENT.SELF_ESTEEM', 'skill', 'helpful', 'Healthy self-esteem (Grade 8 Social Studies) helps a player accept defeat. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G8.CREATI.VERSE.VERSE_LANGUAGE', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'CREA.G7.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'skill', 'essential', 'Analysing a folk song and a story (Grade 7) is the same method for verse and dance. Proposed, to confirm by a CBC Creative Arts and Sports teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES.M_CA8_RO_USELESS', 'CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'Says Creative Arts and Sports do nothing useful for society.', '{"question":"What do Creative Arts and Sports do for society?","wrong_answer":"Nothing useful","correct_answer":"Entertain, keep culture and keep people fit"}'::jsonb, 'The child hears that only examined subjects lead to jobs.', 'Offer "Nothing useful" next to the right answer and ask the question again in a new situation.', 'List people in the county who earn a living from music, art or sport.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES.M_CA8_RO_HEALTH', 'CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'Picks "making people sick" as a role of sport, missing health.', '{"question":"Which role do sports play?","wrong_answer":"Making people sick","correct_answer":"Keeping people fit and healthy"}'::jsonb, 'The child has seen sports injuries and thinks of sport as risky.', 'Offer "Making people sick" next to the right answer and ask the question again in a new situation.', 'Compare a week with daily exercise and a week without.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES.M_CA8_RO_CULTURE', 'CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'Thinks songs and dances make a community forget its past.', '{"question":"How do songs and dances help a community?","wrong_answer":"They make it forget its past","correct_answer":"They pass on culture"}'::jsonb, 'Modern music feels new to the child, so the arts seem to replace tradition.', 'Offer "They make it forget its past" next to the right answer and ask the question again in a new situation.', 'Name a folk song an elder taught the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES.M_CA8_RO_JOB_ONLY_STARS', 'CREA.G8.FOUNDA.ROLES_OF_CREATIVE_ARTS_A.ROLES', 'Thinks only famous stars can earn a living from the arts and sport.', '{"question":"Who can earn a living from Creative Arts and Sports?","wrong_answer":"only famous stars","correct_answer":"many people: coaches, teachers, designers, sound engineers, craftspeople"}'::jsonb, 'The child sees only celebrities on TV.', 'Offer "only famous stars" next to the right answer and ask the question again in a new context.', 'List jobs behind one football match or one concert.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS.M_CA8_VE_STANZA', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS', 'Calls a stanza one word.', '{"question":"What is a stanza?","wrong_answer":"One word","correct_answer":"A group of lines"}'::jsonb, 'The child has not met the word and guesses something small.', 'Offer "One word" next to the right answer and ask the question again in a new situation.', 'Count the groups of lines in a poem: each is a stanza.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS.M_CA8_VE_RHYME', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS', 'Says rhyme is words with the same first sound, mixing it with alliteration.', '{"question":"What is rhyme?","wrong_answer":"Same beginning sounds","correct_answer":"Repeated end sounds"}'::jsonb, 'Both are sound patterns met in the same poetry lessons.', 'Offer "Same beginning sounds" next to the right answer and ask the question again in a new situation.', 'Underline the last words of two lines: cat and hat rhyme.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS.M_CA8_VE_LINE', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS', 'Calls the whole poem a line.', '{"question":"What is a line of verse?","wrong_answer":"The whole poem","correct_answer":"One row of words"}'::jsonb, 'The child uses "line" loosely to mean writing.', 'Offer "The whole poem" next to the right answer and ask the question again in a new situation.', 'Point at one row of words: that is a line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY.M_CA8_FA_AGILITY', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'Mixes agility with endurance.', '{"question":"Which is changing direction quickly?","wrong_answer":"Endurance","correct_answer":"Agility"}'::jsonb, 'Both words are new and are taught together.', 'Offer "Endurance" next to the right answer and ask the question again in a new situation.', 'Zigzag between cones (agility), then jog for five minutes (endurance).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY.M_CA8_FA_ENDURANCE', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'Mixes endurance with agility.', '{"question":"Which is lasting a long time without tiring?","wrong_answer":"Agility","correct_answer":"Endurance"}'::jsonb, 'The child swaps the two new words learnt in one lesson.', 'Offer "Agility" next to the right answer and ask the question again in a new situation.', 'Ask "how long can you keep going?" for endurance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY.M_CA8_FA_ACTIVITY', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'Picks a single quick jump as training for endurance.', '{"question":"Which activity builds endurance?","wrong_answer":"A single quick jump","correct_answer":"Long steady running"}'::jsonb, 'The child thinks any hard effort builds endurance.', 'Offer "A single quick jump" next to the right answer and ask the question again in a new situation.', 'Endurance needs a long, steady effort: compare one jump with a 10-minute jog.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF.M_CA8_BS_LINES', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'Gives the treble lines E G B D F for the bass staff.', '{"question":"What are the lines of the bass staff from the bottom?","wrong_answer":"E G B D F","correct_answer":"G B D F A"}'::jsonb, 'The treble rhyme was learnt first and sticks.', 'Offer "E G B D F" next to the right answer and ask the question again in a new situation.', 'Bass lines: Good Boys Do Fine Always (G B D F A).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF.M_CA8_BS_SPACES', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'Gives the treble spaces F A C E for the bass staff.', '{"question":"What are the spaces of the bass staff from the bottom?","wrong_answer":"F A C E","correct_answer":"A C E G"}'::jsonb, 'FACE is the easiest rhyme and gets used for both staves.', 'Offer "F A C E" next to the right answer and ask the question again in a new situation.', 'Bass spaces: All Cows Eat Grass (A C E G).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF.M_CA8_BS_CLEF', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'Says the bass clef is for high sounds.', '{"question":"The bass clef is used for...","wrong_answer":"High sounds","correct_answer":"Low sounds"}'::jsonb, 'The child does not link "bass" with deep voices.', 'Offer "High sounds" next to the right answer and ask the question again in a new situation.', 'Sing a low note: that is the bass range.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34.M_CA8_T3_BEATS', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'Gives a bar of three-four time two crotchet beats.', '{"question":"How many crotchet beats are in a bar of 3/4?","wrong_answer":"2","correct_answer":"3"}'::jsonb, 'Two-four time was learnt first.', 'Offer "2" next to the right answer and ask the question again in a new situation.', 'Read the top number: 3 beats. Count STRONG weak weak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34.M_CA8_T3_DOTTED', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'Gives a dotted minim two beats, ignoring the dot.', '{"question":"How many beats is a dotted minim?","wrong_answer":"2","correct_answer":"3"}'::jsonb, 'The child does not know a dot adds half the value.', 'Offer "2" next to the right answer and ask the question again in a new situation.', 'A minim is 2, half of 2 is 1, so the dotted minim is 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34.M_CA8_T3_BAR', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'Says a minim alone fills a bar of three-four time.', '{"question":"Which fills a bar of 3/4?","wrong_answer":"A minim alone","correct_answer":"A minim and a crotchet"}'::jsonb, 'The minim is the longest note the child uses often.', 'Offer "A minim alone" next to the right answer and ask the question again in a new situation.', 'Count the minim: 2. One more beat is needed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR.M_CA8_GM_SHARP', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'Says G major has one flat.', '{"question":"G major has one...","wrong_answer":"flat","correct_answer":"sharp"}'::jsonb, 'The child knows "one" but not which kind of sign.', 'Offer "flat" next to the right answer and ask the question again in a new situation.', 'Write G A B C D E F G and play it: F needs to be raised, a sharp.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR.M_CA8_GM_NOTE', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'Names B as the sharp note in G major.', '{"question":"Which note is sharp in G major?","wrong_answer":"B","correct_answer":"F"}'::jsonb, 'The child guesses a note near the start of the scale.', 'Offer "B" next to the right answer and ask the question again in a new situation.', 'Count the steps: the seventh note, F, must be raised.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR.M_CA8_GM_HOME', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'Says G major begins and ends on C.', '{"question":"On which note does G major begin and end?","wrong_answer":"C","correct_answer":"G"}'::jsonb, 'C major was learnt first, so C feels like home.', 'Offer "C" next to the right answer and ask the question again in a new situation.', 'The key name is the home note: G major starts and ends on G.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS.M_CA8_VE_RHYTHM_RHYME', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.VERSE_ELEMENTS', 'Thinks rhythm in verse is the same as rhyme.', '{"question":"What is rhythm in a poem?","wrong_answer":"words that end with the same sound","correct_answer":"the beat made by stressed and unstressed syllables"}'::jsonb, 'Rhythm and rhyme sound alike.', 'Offer "words that end with the same sound" next to the right answer and ask the question again in a new context.', 'Clap a line of a poem; then underline its rhymes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY.M_CA8_FA_AGILITY_SPEED', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.FITNESS_AGILITY', 'Thinks agility is only running fast in a straight line.', '{"question":"Which shows agility: a straight 100 m sprint or a zigzag run?","wrong_answer":"the straight sprint","correct_answer":"the zigzag run"}'::jsonb, 'Fast running looks like the best movement.', 'Offer "the straight sprint" next to the right answer and ask the question again in a new context.', 'Time a straight run and a zigzag run.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF.M_CA8_BS_MIDDLE_C', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.BASS_STAFF', 'Thinks middle C on the bass staff is on the bottom line.', '{"question":"Where is middle C for the bass staff?","wrong_answer":"on the bottom line","correct_answer":"on one ledger line above the staff"}'::jsonb, 'The child moves the treble middle C to the bottom.', 'Offer "on the bottom line" next to the right answer and ask the question again in a new context.', 'Draw both staves: middle C sits on a ledger line between them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34.M_CA8_T3_FOUR_CROTCHETS', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.TIME_34', 'Puts four crotchets in a bar of three-four time.', '{"question":"Is a bar of four crotchets correct in three-four time?","wrong_answer":"yes","correct_answer":"no; it needs three beats"}'::jsonb, 'The child writes the pattern used most often in songs.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Count each bar aloud: 1 2 3, line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR.M_CA8_GM_SHARP_ALL_F', 'CREA.G8.FOUNDA.COMPONENTS_OF_CREATIVE_A.G_MAJOR', 'Sharpens only the first F in a piece in G major.', '{"question":"In G major, is every F played as F sharp?","wrong_answer":"only the first one","correct_answer":"yes, every F"}'::jsonb, 'The child treats the key signature like a one-time accidental.', 'Offer "only the first one" next to the right answer and ask the question again in a new context.', 'Circle every F in a short G major tune.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE.M_CA8_DM_MEANING', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'Says dominance means every part of the picture is equal.', '{"question":"What is dominance in a picture?","wrong_answer":"Every part is equal","correct_answer":"The main feature that catches the eye"}'::jsonb, 'The child mixes dominance with balance.', 'Offer "Every part is equal" next to the right answer and ask the question again in a new situation.', 'Ask what the eye sees first in a poster: that is dominant.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE.M_CA8_DM_HOW', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'Makes a feature the smallest and dullest to make it dominant.', '{"question":"Which makes a feature dominant?","wrong_answer":"Making it the smallest and dullest","correct_answer":"Making it large or bright"}'::jsonb, 'The child reads the question too fast.', 'Offer "Making it the smallest and dullest" next to the right answer and ask the question again in a new situation.', 'Paint a red pot among grey ones; which stands out?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE.M_CA8_DM_OTHER', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'Calls the less important parts dominant.', '{"question":"What are the less important parts called?","wrong_answer":"Dominant parts","correct_answer":"Subordinate parts"}'::jsonb, 'The child has not met "subordinate".', 'Offer "Dominant parts" next to the right answer and ask the question again in a new situation.', 'Main feature: dominant. The rest: subordinate.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY.M_CA8_CP_RED', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY', 'Gives orange as the complement of red, picking the colour next to it.', '{"question":"Which colour is complementary to red?","wrong_answer":"Orange","correct_answer":"Green"}'::jsonb, 'The child looks beside red on the wheel, not across.', 'Offer "Orange" next to the right answer and ask the question again in a new situation.', 'Draw a line through the centre of the wheel from red: it lands on green.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY.M_CA8_CP_BLUE', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY', 'Gives green as the complement of blue, picking a neighbour.', '{"question":"Which colour is complementary to blue?","wrong_answer":"Green","correct_answer":"Orange"}'::jsonb, 'Green sits next to blue and looks related.', 'Offer "Green" next to the right answer and ask the question again in a new situation.', 'Go across the wheel from blue: orange.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY.M_CA8_CP_WHEEL', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY', 'Says complementary colours sit side by side on the wheel.', '{"question":"Where do complementary colours sit on the wheel?","wrong_answer":"Side by side","correct_answer":"Opposite each other"}'::jsonb, '"Complement" sounds like "go well together", so the child thinks of neighbours.', 'Offer "Side by side" next to the right answer and ask the question again in a new situation.', 'Complements are opposite; neighbours are analogous.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE.M_CA8_DM_TWO_MAIN', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.DOMINANCE', 'Makes two features equally dominant in one picture.', '{"question":"Should a picture have one dominant feature or several?","wrong_answer":"several equal ones","correct_answer":"one main feature"}'::jsonb, 'The child wants everything to be noticed.', 'Offer "several equal ones" next to the right answer and ask the question again in a new context.', 'Show a poster with two big competing pictures.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY.M_CA8_CP_MIX_GREY', 'CREA.G8.CREATI.DRAWING_AND_PAINTING.COMPLEMENTARY', 'Thinks mixing complements makes a brighter colour.', '{"question":"Red and green paint are mixed. What do you get?","wrong_answer":"a bright new colour","correct_answer":"a dull brown or grey"}'::jsonb, 'Placed side by side they look bright, so the child expects the mix to be bright.', 'Offer "a bright new colour" next to the right answer and ask the question again in a new context.', 'Mix a little of each on a palette.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.RHYTHM.THREE_FOUR.M_CA8_TF_STRONG_LAST', 'CREA.G8.CREATI.RHYTHM.THREE_FOUR', 'Puts the strong beat on the third beat of the bar.', '{"question":"In three-four time, which beat is strong?","wrong_answer":"the third","correct_answer":"the first"}'::jsonb, 'The child hears the bar line as an ending, so stresses the beat before it.', 'Offer "the third" next to the right answer and ask the question again in a new context.', 'Count STRONG weak weak and step on the first beat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.RHYTHM.THREE_FOUR.M_CA8_TF_MARCH', 'CREA.G8.CREATI.RHYTHM.THREE_FOUR', 'Says three-four time suits a march.', '{"question":"Which suits three-four time: a march or a waltz?","wrong_answer":"a march","correct_answer":"a waltz"}'::jsonb, 'Marches are the time-signature examples the child knows best.', 'Offer "a march" next to the right answer and ask the question again in a new context.', 'March to 1 2, then sway to 1 2 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.RHYTHM.THREE_FOUR.M_CA8_TF_BAR_COUNT', 'CREA.G8.CREATI.RHYTHM.THREE_FOUR', 'Writes a four-bar pattern whose bars hold different numbers of beats.', '{"question":"Must every bar of a three-four pattern hold three beats?","wrong_answer":"no, it can change","correct_answer":"yes, every bar"}'::jsonb, 'The child writes by ear and does not count.', 'Offer "no, it can change" next to the right answer and ask the question again in a new context.', 'Write the beat count under each bar.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.RHYTHM.THREE_FOUR.M_CA8_TF_TOP_NUMBER', 'CREA.G8.CREATI.RHYTHM.THREE_FOUR', 'Reads the 4 of three-four as the number of beats in a bar.', '{"question":"In three-four time, what does the top number 3 tell you?","wrong_answer":"the note value","correct_answer":"three beats in each bar"}'::jsonb, 'The child swaps the meaning of the two numbers.', 'Offer "the note value" next to the right answer and ask the question again in a new context.', 'Top: how many beats. Bottom: what kind of beat (crotchet).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE.M_CA8_MD_RACE', 'CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE', 'Names the 100 metres as a middle distance race.', '{"question":"Which is a middle distance race?","wrong_answer":"100 metres","correct_answer":"800 metres"}'::jsonb, 'The 100 m is the race the child hears about most.', 'Offer "100 metres" next to the right answer and ask the question again in a new situation.', 'Sort 100, 400, 800, 1 500 and 5 000 m into sprint, middle and long.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE.M_CA8_MD_MONTAGE', 'CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE', 'Thinks a montage is one plain picture.', '{"question":"What is a montage?","wrong_answer":"One plain picture","correct_answer":"A picture made by combining many pieces"}'::jsonb, 'The child has forgotten Grade 4 montage.', 'Offer "One plain picture" next to the right answer and ask the question again in a new situation.', 'Show a montage of runners cut from newspapers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE.M_CA8_MD_PACE', 'CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE', 'Thinks middle distance is run at full speed all the way.', '{"question":"What do middle distance runners need?","wrong_answer":"Only a fast start","correct_answer":"Pace and endurance"}'::jsonb, 'Races look fast to watch.', 'Offer "Only a fast start" next to the right answer and ask the question again in a new situation.', 'Run 800 m flat out versus at an even pace; compare the last lap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE.M_CA8_MD_LANE_ALL', 'CREA.G8.CREATI.MIDDLE_DISTANCE_RACES_AN.MIDDLE_DISTANCE', 'Thinks 800 m runners stay in their lanes for the whole race.', '{"question":"In the 800 m, do runners stay in lanes all the way?","wrong_answer":"yes","correct_answer":"no; they may break to the inside lane after the first bend"}'::jsonb, 'The child has watched sprints, which stay in lanes.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Watch an 800 m start: they cut in after the break line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MELODY.MELODY_METHODS.M_CA8_MY_HOME', 'CREA.G8.CREATI.MELODY.MELODY_METHODS', 'Ends a G major melody on C.', '{"question":"On which note does a melody in G major end?","wrong_answer":"C","correct_answer":"G"}'::jsonb, 'C major was the first key, so C still feels like home.', 'Offer "C" next to the right answer and ask the question again in a new situation.', 'Sing the melody ending on C and on G.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MELODY.MELODY_METHODS.M_CA8_MY_ANSWER', 'CREA.G8.CREATI.MELODY.MELODY_METHODS', 'Thinks an answering phrase must copy the opening phrase exactly.', '{"question":"What is an answering phrase?","wrong_answer":"A copy of the opening phrase","correct_answer":"A phrase that replies to the opening phrase"}'::jsonb, 'The child knows repetition helps and overdoes it.', 'Offer "A copy of the opening phrase" next to the right answer and ask the question again in a new situation.', 'Sing a question phrase and answer with a similar start but a new ending on G.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MELODY.MELODY_METHODS.M_CA8_MY_STEP', 'CREA.G8.CREATI.MELODY.MELODY_METHODS', 'Thinks a melody moves only by big leaps.', '{"question":"How does a melody move?","wrong_answer":"Only by huge leaps","correct_answer":"By steps and leaps"}'::jsonb, 'Leaps sound exciting.', 'Offer "Only by huge leaps" next to the right answer and ask the question again in a new situation.', 'Sing a known song and count steps and leaps.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.MELODY.MELODY_METHODS.M_CA8_MY_QUESTION_HOME', 'CREA.G8.CREATI.MELODY.MELODY_METHODS', 'Ends the opening (question) phrase on the home note G.', '{"question":"Where should a question phrase usually end?","wrong_answer":"on G, the home note","correct_answer":"away from home, often on D"}'::jsonb, 'The child ends every phrase on the home note.', 'Offer "on G, the home note" next to the right answer and ask the question again in a new context.', 'Sing a question ending on D: it wants an answer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.NETBALL.NETBALL.M_CA8_NB_PLAYERS', 'CREA.G8.CREATI.NETBALL.NETBALL', 'Says a netball team has eleven players, taking the football number.', '{"question":"How many players are in a netball team?","wrong_answer":"Eleven","correct_answer":"Seven"}'::jsonb, 'Football is the team game the child knows best.', 'Offer "Eleven" next to the right answer and ask the question again in a new situation.', 'Count the seven positions with bibs: GS, GA, WA, C, WD, GD, GK.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.NETBALL.NETBALL.M_CA8_NB_RUN', 'CREA.G8.CREATI.NETBALL.NETBALL', 'Says a netball player may run with the ball as far as she likes.', '{"question":"May a netball player run with the ball?","wrong_answer":"Yes, as far as she likes","correct_answer":"No, she must pass or shoot"}'::jsonb, 'In football and rugby players move with the ball.', 'Offer "Yes, as far as she likes" next to the right answer and ask the question again in a new situation.', 'Land, pivot on one foot, then pass.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.NETBALL.NETBALL.M_CA8_NB_SECONDS', 'CREA.G8.CREATI.NETBALL.NETBALL', 'Says a player may hold the ball for ten seconds.', '{"question":"For how long may a player hold the ball?","wrong_answer":"Ten seconds","correct_answer":"Three seconds"}'::jsonb, 'The child guesses a round number.', 'Offer "Ten seconds" next to the right answer and ask the question again in a new situation.', 'Count three seconds aloud while holding the ball.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.NETBALL.NETBALL.M_CA8_NB_PIVOT_BOTH', 'CREA.G8.CREATI.NETBALL.NETBALL', 'Moves both feet after landing, thinking a pivot allows it.', '{"question":"After landing with the ball, what may you do?","wrong_answer":"step with both feet","correct_answer":"pivot on the landing foot only"}'::jsonb, 'The child sees turning and thinks any step is allowed.', 'Offer "step with both feet" next to the right answer and ask the question again in a new context.', 'Mark the landing foot with chalk and pivot on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR.M_CA8_FB_TIE', 'CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR', 'Thinks cloth is tied only to make it smaller for storage, not to resist the dye.', '{"question":"In tie and dye, why is cloth tied?","wrong_answer":"To make it smaller for storage","correct_answer":"To stop it dyeing evenly everywhere so patterns form"}'::jsonb, 'The child sees tying as tidying.', 'Offer "To make it smaller for storage" next to the right answer and ask the question again in a new situation.', 'Untie a dyed piece and show the light patterns where it was tied.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR.M_CA8_FB_STENCIL', 'CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR', 'Calls pleating the technique that uses a cut-out design.', '{"question":"Which technique uses a cut-out design?","wrong_answer":"Pleating","correct_answer":"Stencil printing"}'::jsonb, 'Both are new words in the same lesson.', 'Offer "Pleating" next to the right answer and ask the question again in a new situation.', 'Hold up a stencil: colour goes through the holes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR.M_CA8_FB_PLEAT', 'CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR', 'Calls stencil printing the technique that folds cloth.', '{"question":"Which technique folds cloth into folds?","wrong_answer":"Stencil printing","correct_answer":"Pleating"}'::jsonb, 'The child swaps the two new words.', 'Offer "Stencil printing" next to the right answer and ask the question again in a new situation.', 'Fold paper like a fan: that is pleating.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR.M_CA8_FB_MARBLE_SAME', 'CREA.G8.CREATI.FABRIC_DECORATION.FABRIC_DECOR', 'Thinks marbling gives the same pattern as tie and dye with rings.', '{"question":"What kind of pattern does marbling give?","wrong_answer":"neat rings","correct_answer":"irregular veins like marble"}'::jsonb, 'All tie-dye patterns look alike to the child.', 'Offer "neat rings" next to the right answer and ask the question again in a new context.', 'Crumple and bind cloth, dye it, and compare with a ring tie.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH.M_CA8_RT_BLOW', 'CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH', 'Says the recorder is blown as hard as possible.', '{"question":"How should you blow a descant recorder?","wrong_answer":"As hard as possible","correct_answer":"Gently and steadily"}'::jsonb, 'The child thinks louder breath means better sound.', 'Offer "As hard as possible" next to the right answer and ask the question again in a new situation.', 'Blow hard, then gently; hear the squeak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH.M_CA8_RT_P', 'CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH', 'Says p means loud, swapping piano and forte.', '{"question":"What does p mean in music?","wrong_answer":"Loud","correct_answer":"Soft"}'::jsonb, 'Both letters are new and sit under the notes.', 'Offer "Loud" next to the right answer and ask the question again in a new situation.', 'p for piano: soft. f for forte: loud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH.M_CA8_RT_REPEAT', 'CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH', 'Says a repeat sign means stop playing.', '{"question":"What does a repeat sign mean?","wrong_answer":"Stop playing","correct_answer":"Play the section again"}'::jsonb, 'The double bar looks like the end mark.', 'Offer "Stop playing" next to the right answer and ask the question again in a new situation.', 'Play to the repeat sign and go back to the start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH.M_CA8_RT_CRESC', 'CREA.G8.CREATI.DESCANT_RECORDER.RECORDER_TECH', 'Thinks a crescendo means play faster.', '{"question":"What does crescendo mean?","wrong_answer":"get faster","correct_answer":"get gradually louder"}'::jsonb, 'Both getting faster and louder feel like "more".', 'Offer "get faster" next to the right answer and ask the question again in a new context.', 'Play a scale getting louder at the same speed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VERSE.VERSE_LANGUAGE.M_CA8_VL_SIMILE', 'CREA.G8.CREATI.VERSE.VERSE_LANGUAGE', 'Calls a metaphor ("the moon is a silver coin") a simile.', '{"question":"Which is a simile?","wrong_answer":"The moon is a silver coin","correct_answer":"as bright as the moon"}'::jsonb, 'Both compare two things, so the child mixes them.', 'Offer "The moon is a silver coin" next to the right answer and ask the question again in a new situation.', 'Look for "like" or "as": only then is it a simile.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VERSE.VERSE_LANGUAGE.M_CA8_VL_METAPHOR', 'CREA.G8.CREATI.VERSE.VERSE_LANGUAGE', 'Calls a simile ("as fast as a cheetah") a metaphor.', '{"question":"Which is a metaphor?","wrong_answer":"as fast as a cheetah","correct_answer":"Time is a thief"}'::jsonb, 'The child swaps the two names.', 'Offer "as fast as a cheetah" next to the right answer and ask the question again in a new situation.', 'Metaphor says one thing IS another, with no "like" or "as".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VERSE.VERSE_LANGUAGE.M_CA8_VL_REPEAT', 'CREA.G8.CREATI.VERSE.VERSE_LANGUAGE', 'Thinks repetition in verse is a mistake.', '{"question":"Why repeat a line in verse?","wrong_answer":"To make mistakes","correct_answer":"To stress an idea"}'::jsonb, 'In compositions repetition is marked wrong.', 'Offer "To make mistakes" next to the right answer and ask the question again in a new situation.', 'Read a poem with a refrain and feel the stress it gives.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VERSE.VERSE_LANGUAGE.M_CA8_VL_PERSON', 'CREA.G8.CREATI.VERSE.VERSE_LANGUAGE', 'Thinks personification is describing a person.', '{"question":"Which is personification?","wrong_answer":"The old man walked slowly","correct_answer":"The wind whispered through the trees"}'::jsonb, 'The word has "person" in it.', 'Offer "The old man walked slowly" next to the right answer and ask the question again in a new context.', 'Find things that are not people doing people actions.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL.M_CA8_VO_PLAYERS', 'CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL', 'Says a volleyball team has eleven players on court.', '{"question":"How many players are on the court for a volleyball team?","wrong_answer":"Eleven","correct_answer":"Six"}'::jsonb, 'Eleven is the football number the child knows.', 'Offer "Eleven" next to the right answer and ask the question again in a new situation.', 'Draw the court: three at the front, three at the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL.M_CA8_VO_SERVE', 'CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL', 'Says the overarm serve is hit with the feet.', '{"question":"How is the overarm serve hit?","wrong_answer":"With the feet","correct_answer":"With one open hand above the head"}'::jsonb, 'The child guesses from football.', 'Offer "With the feet" next to the right answer and ask the question again in a new situation.', 'Toss the ball and hit it with an open hand above the head.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL.M_CA8_VO_TOUCH', 'CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL', 'Says a team has ten touches before sending the ball over.', '{"question":"How many touches does a team have before sending the ball over?","wrong_answer":"Ten","correct_answer":"Three"}'::jsonb, 'The child does not know there is a limit.', 'Offer "Ten" next to the right answer and ask the question again in a new situation.', 'Play dig, volley, spike: three touches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL.M_CA8_VO_VOLLEY_PALMS', 'CREA.G8.CREATI.VOLLEYBALL.VOLLEYBALL', 'Volleys the ball with flat palms, slapping it.', '{"question":"Which part of the hand touches the ball in a volley?","wrong_answer":"flat palms","correct_answer":"the fingertips and pads"}'::jsonb, 'The child slaps to get power.', 'Offer "flat palms" next to the right answer and ask the question again in a new context.', 'Make a window with the hands above the forehead and catch the ball on the fingers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES.M_CA8_FD_ISUKUTI', 'CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES', 'Gives isukuti to the Maasai, swapping it with adumu.', '{"question":"Which community is known for isukuti?","wrong_answer":"Maasai","correct_answer":"Luhya"}'::jsonb, 'Both are famous energetic dances seen on TV.', 'Offer "Maasai" next to the right answer and ask the question again in a new situation.', 'Match: isukuti (Luhya drums), adumu (Maasai jumping).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES.M_CA8_FD_ADUMU', 'CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES', 'Gives adumu to the Luhya.', '{"question":"Which community is known for the jumping dance adumu?","wrong_answer":"Luhya","correct_answer":"Maasai"}'::jsonb, 'The child swaps the two best-known dances.', 'Offer "Luhya" next to the right answer and ask the question again in a new situation.', 'Picture the high jumps of Maasai morans: adumu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES.M_CA8_FD_CHAKACHA', 'CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES', 'Places chakacha in the highlands.', '{"question":"Which region is known for chakacha?","wrong_answer":"Highlands","correct_answer":"Coast"}'::jsonb, 'The child does not know chakacha comes from the Swahili coast.', 'Offer "Highlands" next to the right answer and ask the question again in a new situation.', 'Show the coast on the map and play chakacha rhythm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES.M_CA8_FD_ONE_DANCE', 'CREA.G8.CREATI.KENYAN_FOLK_DANCE.FOLK_DANCES', 'Thinks each community has only one folk dance.', '{"question":"Does a community have only one folk dance?","wrong_answer":"yes","correct_answer":"no; different dances for different occasions"}'::jsonb, 'The child links each community with its most famous dance.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'List dances for a wedding, a harvest and an initiation in one community.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY.M_CA8_BK_COIL', 'CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY', 'Says coil basketry is weaving straight strips.', '{"question":"What is coil basketry?","wrong_answer":"Weaving straight strips","correct_answer":"Winding a coil in a spiral and stitching it"}'::jsonb, 'Weaving was the first basket method learnt.', 'Offer "Weaving straight strips" next to the right answer and ask the question again in a new situation.', 'Wind a rope of grass in a spiral and stitch it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY.M_CA8_BK_MATERIAL', 'CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY', 'Names iron as a material for coil baskets.', '{"question":"Which material suits coil baskets?","wrong_answer":"Iron","correct_answer":"Grass or sisal"}'::jsonb, 'The child lists strong materials.', 'Offer "Iron" next to the right answer and ask the question again in a new situation.', 'Ask what bends and can be stitched: grass, sisal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY.M_CA8_BK_ITEM', 'CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY', 'Names a brick as something made by coiling.', '{"question":"Which can be made by coiling?","wrong_answer":"A brick","correct_answer":"A tray"}'::jsonb, 'The child guesses any made object.', 'Offer "A brick" next to the right answer and ask the question again in a new situation.', 'Show a coiled tray and a coiled basket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY.M_CA8_BK_START_EDGE', 'CREA.G8.CREATI.INDIGENOUS_KENYAN_CRAFT_.BASKETRY', 'Starts a coiled basket from the outer edge.', '{"question":"Where does a coiled basket start?","wrong_answer":"at the outer edge","correct_answer":"at the centre of the base"}'::jsonb, 'The child thinks of drawing the outline first.', 'Offer "at the outer edge" next to the right answer and ask the question again in a new context.', 'Show a coil growing from the centre outward.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES.M_CA8_SS_BACK', 'CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES', 'Says inverted breaststroke is swum on the front.', '{"question":"In inverted breaststroke the swimmer lies on...","wrong_answer":"The front","correct_answer":"The back"}'::jsonb, 'Breaststroke is a front stroke, so the child keeps it there.', 'Offer "The front" next to the right answer and ask the question again in a new situation.', '"Inverted" means turned over: on the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES.M_CA8_SS_TREAD', 'CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES', 'Says water treading means lying flat.', '{"question":"What is water treading?","wrong_answer":"Lying flat on the water","correct_answer":"Staying upright in deep water"}'::jsonb, 'The child mixes it with floating.', 'Offer "Lying flat on the water" next to the right answer and ask the question again in a new situation.', 'Show treading upright, head above water, legs moving.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES.M_CA8_SS_SAFETY', 'CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES', 'Says a learner may swim alone at any time.', '{"question":"When should a learner swim?","wrong_answer":"Alone at any time","correct_answer":"With a lifeguard or teacher"}'::jsonb, 'Confident swimmers feel safe.', 'Offer "Alone at any time" next to the right answer and ask the question again in a new situation.', 'Name what could go wrong in deep water alone.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES.M_CA8_SS_TREAD_STILL', 'CREA.G8.CREATI.SWIMMING.SWIMMING_STROKES', 'Thinks treading water means keeping still.', '{"question":"Do you keep still when treading water?","wrong_answer":"yes","correct_answer":"no; arms and legs keep moving gently"}'::jsonb, 'The child sees a calm head and thinks the body is still.', 'Offer "yes" next to the right answer and ask the question again in a new context.', 'Watch a swimmer''s legs under water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES.M_CA8_TG_RULE', 'CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES', 'Thinks nothing happens when the chaser touches a runner.', '{"question":"What happens when the chaser touches a runner?","wrong_answer":"Nothing happens","correct_answer":"The runner becomes the chaser"}'::jsonb, 'The child has played chasing without the swap rule.', 'Offer "Nothing happens" next to the right answer and ask the question again in a new situation.', 'Play one round: the touched runner becomes the chaser.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES.M_CA8_TG_BENEFIT', 'CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES', 'Says tag games make people less fit.', '{"question":"What do tagging games build?","wrong_answer":"Weak muscles","correct_answer":"Speed and agility"}'::jsonb, 'The child sees them as play only.', 'Offer "Weak muscles" next to the right answer and ask the question again in a new situation.', 'Feel the heartbeat after a tag game.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES.M_CA8_TG_KIND', 'CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES', 'Names chess as a tagging game.', '{"question":"Which is a tagging game?","wrong_answer":"Chess","correct_answer":"A chasing game"}'::jsonb, 'The child lists any game.', 'Offer "Chess" next to the right answer and ask the question again in a new situation.', 'Ask: does someone chase and touch?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES.M_CA8_TG_PUSH', 'CREA.G8.CREATI.KENYAN_INDIGENOUS_GAMES.TAG_GAMES', 'Thinks pushing a runner hard counts as a tag.', '{"question":"How should a chaser tag a runner?","wrong_answer":"push them hard","correct_answer":"a light touch"}'::jsonb, 'The child wants to be sure the tag counts.', 'Offer "push them hard" next to the right answer and ask the question again in a new context.', 'Practise a gentle touch on the shoulder.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP.M_CA8_SP_CHEAT', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP', 'Picks cheating to win as sportsmanship.', '{"question":"Which shows sportsmanship?","wrong_answer":"Cheating to win","correct_answer":"Playing fairly"}'::jsonb, 'The child has seen cheats win and be praised.', 'Offer "Cheating to win" next to the right answer and ask the question again in a new situation.', 'Ask how the other team feels when they lose to a cheat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP.M_CA8_SP_DEFEAT', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP', 'Thinks a good sport accepts defeat with anger.', '{"question":"How should a good sport accept defeat?","wrong_answer":"With anger","correct_answer":"With respect"}'::jsonb, 'The child sees anger as showing you care.', 'Offer "With anger" next to the right answer and ask the question again in a new situation.', 'Watch a team shake hands after losing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP.M_CA8_SP_OFFICIAL', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP', 'Thinks players should insult referees.', '{"question":"How should players treat referees?","wrong_answer":"Insult them","correct_answer":"Respect their decisions"}'::jsonb, 'The child copies fans shouting at matches.', 'Offer "Insult them" next to the right answer and ask the question again in a new situation.', 'Discuss what happens to a game without a respected referee.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP.M_CA8_SP_WIN_GLOAT', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.SPORTSMANSHIP', 'Thinks a good winner may mock the losing team.', '{"question":"How should a winning team behave?","wrong_answer":"laugh at the losers","correct_answer":"shake hands and thank them"}'::jsonb, 'Celebrating feels like the reward for winning.', 'Offer "laugh at the losers" next to the right answer and ask the question again in a new context.', 'Role-play winning with respect.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA8_AN_OPINION_ONLY', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Analyses a verse performance only by saying it was good.', '{"question":"Which is an analysis of a verse performance?","wrong_answer":"it was good","correct_answer":"the repeated line \"we need water\" stresses the message about drought"}'::jsonb, 'The child confuses giving an opinion with analysing.', 'Offer "it was good" next to the right answer and ask the question again in a new context.', 'Ask "what did you hear that shows that?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA8_AN_FORMATION_COSTUME', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Calls the dancers'' circle their costume.', '{"question":"Dancers move in a circle. Which term describes this?","wrong_answer":"costume","correct_answer":"formation"}'::jsonb, 'The child mixes terms learnt together.', 'Offer "costume" next to the right answer and ask the question again in a new context.', 'Worn: costume. Pattern of dancers: formation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA8_AN_MESSAGE_TOPIC', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Gives the topic of a verse when asked for its message.', '{"question":"A verse is about trees. What is its message?","wrong_answer":"trees","correct_answer":"we must plant and protect trees"}'::jsonb, 'The child names the subject, not what the poet says about it.', 'Offer "trees" next to the right answer and ask the question again in a new context.', 'Ask "what does the poet want us to think or do?"', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS.M_CA8_AN_COMMUNITY_GUESS', 'CREA.G8.APPREC.ANALYSIS_OF_CREATIVE_ART.ANALYSIS', 'Names a dance''s community from the costume colour alone.', '{"question":"How do you know which community a dance comes from?","wrong_answer":"from the colour of the costume only","correct_answer":"from its steps, songs, instruments, language and occasion together"}'::jsonb, 'Bright costumes are the first thing the child notices.', 'Offer "from the colour of the costume only" next to the right answer and ask the question again in a new context.', 'List all the clues in one performance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
